                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                raise ApiError(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")
            raise ApiError(HTTPStatus.NOT_FOUND, "route not found")
