                # itself has still been flushed and atomically replaced.
                pass
        finally:
            if temp_name is not None:
                try:
                    os.unlink(temp_name)
                except FileNotFoundError:
                    pass

    def _persist_after_purge_locked(self) -> None:
        if self._purge_expired_locked():
            self._persist_locked()

