            if previous is None:
                return False
            try:
                self._persist_locked()
            except Exception:
                self.entries[key] = previous
                raise
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._persist_after_purge_locked()
            return sorted(self.entries)


